<script>document.addEventListener('DOMContentLoaded',()=>{const type=document.getElementById('target_type');const target=document.getElementById('target_id');const field=document.getElementById('field_name');const filter=(select)=>{const selected=select.value;[...select.options].forEach((option)=>{if(!option.dataset.targetType)return;option.hidden=option.dataset.targetType!==type.value;option.disabled=option.hidden;});if(select.selectedOptions[0]?.disabled)select.value='';if(selected&&[...select.options].some((option)=>option.value===selected&&!option.disabled))select.value=selected;};const refresh=()=>{filter(target);filter(field);};type.addEventListener('change',refresh);refresh();});</script>
